"""Self-contained publishing console; no remote assets or client dependencies."""
import html
from datetime import datetime, timezone


def render(metadata, install_url, releases=(), apps=()):
  e = lambda value: html.escape(str(value), quote=True)
  bundle = metadata['bundle_id']
  navigation = ''.join(f'<a class="app {"selected" if app["bundle_id"] == bundle else ""}" href="{e(app["latest_url"])}"><span class="monogram">{e(app["name"][:1])}</span>{e(app["name"])}</a>' for app in apps)
  if not navigation:
    navigation = f'<a class="app selected" href="#"><span class="monogram">{e(metadata["name"][:1])}</span>{e(metadata["name"])}</a>'
  releases = list(releases) or [metadata]
  rows = []
  for release in releases or [metadata]:
    stamp = release.get('published_at', '')
    try:
      date = datetime.fromisoformat(stamp)
      stamp = date.strftime('%b %d, %H:%M UTC')
    except ValueError:
      stamp = '—'
    rows.append(f'<tr><td><a href="{e(release.get("install_page_url", "#"))}">#{e(release["build"])} <span>{e(release["version"])}</span></a></td><td>{e(release.get("configuration", "—"))}</td><td class="date">{e(stamp)}</td><td class="action"><a class="icon" href="{e(release.get("install_url", install_url))}" aria-label="Install build {e(release["build"])}" title="Install build {e(release["build"])}">↓</a></td></tr>')
  expired = datetime.fromisoformat(metadata['expires_at']) <= datetime.now(timezone.utc)
  primary = '<span class="expired">Signing expired</span>' if expired else f'<a class="install" href="{e(install_url)}">Install ↗</a>'
  hidden = ''
  if not any(r.get('configuration') for r in releases):
    hidden += 'th:nth-child(2),td:nth-child(2){display:none}'
  if not any(r.get('published_at') for r in releases):
    hidden += 'th:nth-child(3),td:nth-child(3){display:none}'
  return ('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>''' + e(metadata['name']) + ''' · iOS Publish</title><style>
:root{font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#eceeed;background:#121514;color-scheme:dark;font-variant-numeric:tabular-nums;-webkit-font-smoothing:antialiased}*{box-sizing:border-box}body{margin:0}a{color:inherit;text-decoration:none}button{font:inherit;color:inherit;cursor:pointer}a:focus-visible,button:focus-visible,summary:focus-visible{outline:2px solid #9dcca4;outline-offset:4px}aside{width:232px;position:fixed;inset:0 auto 0 0;border-right:1px solid #ffffff12;padding:28px 20px}.brand{font-size:19px;font-weight:600;display:block;margin:0 8px 40px}.brand span{color:#9dcca4;margin-right:10px}.app{display:flex;align-items:center;gap:12px;padding:10px;border-radius:6px;margin-bottom:6px;overflow-wrap:anywhere}.app:hover,.icon:hover{background:#ffffff0b}.selected{background:#ffffff08;border:1px solid #ffffff0b}.monogram{display:grid;place-items:center;flex-shrink:0;width:32px;height:32px;border-radius:6px;background:#beb6e3;color:#252136;font-weight:600}main{margin-left:232px;padding:48px 56px;max-width:1500px;min-width:0;isolation:isolate}header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:32px}h1{font-size:42px;font-weight:600;letter-spacing:-.04em;margin:0}header p{font-family:ui-monospace,monospace;color:#a2aaa6;margin:0;overflow-wrap:anywhere}.icon{display:inline-grid;place-items:center;min-width:36px;min-height:36px;border:1px solid #ffffff16;border-radius:6px;background:transparent;font-size:20px}.latest{display:flex;align-items:center;flex-wrap:wrap;gap:22px;border:1px solid #ffffff16;border-radius:6px;padding:24px;margin-bottom:24px}.label{color:#a4d8ac}.label::before{content:"";display:inline-block;width:9px;height:9px;border-radius:50%;background:#a4d8ac;margin-right:10px}.version{font-size:32px;font-weight:600;letter-spacing:-.025em}.build{color:#a2aaa6;font-size:20px}.configuration{border:1px solid #ffffff16;border-radius:20px;padding:2px 10px}.size{color:#a2aaa6}.install{margin-left:auto;background:#9dcca4;color:#112116;border-radius:5px;padding:8px 24px;font-weight:600;min-width:150px;text-align:center}.install:hover{background:#b1dab6}.expired{margin-left:auto;color:#e4b789}table{border-collapse:collapse;width:100%;text-align:left}th{font-weight:400;color:#a2aaa6;white-space:nowrap;padding:12px 4px}td{padding:14px 4px;border-top:1px solid #ffffff16}td span{color:#a2aaa6;margin-left:12px}.action{text-align:right;width:48px}.action .icon{border:0}.date{color:#a2aaa6}details.mobile{display:none}.toast{position:fixed;bottom:24px;right:24px;background:#272d29;padding:10px 16px;border:1px solid #ffffff20;border-radius:6px}.toast:empty{display:none}@media(max-width:800px){aside{display:none}main{margin:0;padding:24px}details.mobile{display:block;border-bottom:1px solid #ffffff16;padding:16px 24px}summary{cursor:pointer;min-height:32px}details nav{padding-top:16px}h1{font-size:34px}header p{font-size:14px}.latest{gap:12px;padding:20px}.version{font-size:28px}.install{width:100%;margin:8px 0 0;min-height:48px;padding:12px}.icon{min-width:48px;min-height:48px}.label{width:100%}table{font-size:16px}.date{display:none}th:nth-child(3){display:none}td span{display:block;margin:0;color:#a2aaa6}header{margin-bottom:24px}header>div{min-width:0}}
''' + hidden + '''</style></head><body><aside><a class="brand" href="''' + e(metadata.get('console_url', '#')) + '''"><span>◇</span>iOS Publish</a><nav aria-label="Apps">''' + navigation + '''</nav></aside><details class="mobile"><summary>iOS Publish</summary><nav aria-label="Apps">''' + navigation + '''</nav></details><main><header><div><h1>''' + e(metadata['name']) + '''</h1><p>''' + e(bundle) + '''</p></div><button class="icon" id="copy" aria-label="Copy install link" title="Copy install link">⧉</button></header><section class="latest" aria-label="Latest build"><div class="label">''' + ('Expired' if expired else metadata.get('display_label', 'Latest')) + '''</div><div class="version">''' + e(metadata['version']) + '''</div><div class="build">#''' + e(metadata['build']) + '''</div>''' + (f'<div class="configuration">{e(metadata["configuration"])}</div>' if metadata.get('configuration') else '') + '''<div class="size">''' + f'{metadata["size_bytes"] / 1048576:.1f} MB' + '''</div>''' + primary + '''</section><table><thead><tr><th scope="col">Build</th><th scope="col">Configuration</th><th scope="col">Published</th><th scope="col"><span class="sr" aria-label="Install"></span></th></tr></thead><tbody>''' + ''.join(rows) + '''</tbody></table></main><div class="toast" role="status" id="message"></div><script>
document.getElementById('copy').addEventListener('click',async()=>{const message=document.getElementById('message');try{await navigator.clipboard.writeText(location.href);message.textContent='Link copied'}catch{message.textContent='Copy the address from your browser'}setTimeout(()=>message.textContent='',3000)});
</script></body></html>''').encode()
